// === Tab: mySketch.js ===
const n = 3000; // number of particles
var particles = []; // array holding the particle objects
const LIFESPAN = 200; // number of frames each particle lives until it resets
const PHI = (1 + Math.sqrt(5)) / 2; // constant used for particle size calculation

function setup() {
	//createCanvas(windowWidth, windowHeight); // full screen mode
	createCanvas(400, 400);
	noStroke();
	// initialize the particle array:
	for (i = 0; i < n; i++) {
		particles.push(new Particle(int(Math.random() * LIFESPAN)));
	}
}

function draw() {
	background(0);
	for (i = 0; i < n; i++) {
		let p = particles[i];
		p.move();
		p.display();
		if (p.age > LIFESPAN) {
			particles[i] = new Particle(0);
		}
	}
}

function perlinVectorAt(x, y, z) {
	let scale = 100;
	x /= scale;
	y /= scale;
	let vx = noise(x, y, z) *2 -1;
	let vy = noise(x+PHI, y+PHI, z+PHI) *2 -1;
	return createVector(vx, vy);
}


class Particle {
	constructor(age) {
		this.age = age;
		this.x = Math.random() * width;
		this.y = Math.random() * height;
		this.loc = createVector(this.x, this.y);
	}

	move() {
		let vec =  perlinVectorAt(this.loc.x, this.loc.y, frameCount/100);
		this.loc.add(vec.mult(3));
		this.age++;
	}

	display() {
		push();
		let ageNorm = this.age / float(LIFESPAN);
		let r = ageNorm * 256;
		let b = (1-ageNorm) * 256;
		let alpha = 64;
		fill(r, 0, b, alpha);
		//let size = 10 * Math.E ** -(2.9*(this.age/LIFESPAN-0.5) ** 2); // complicated size calculation
		let size = 20 * (0.5 -Math.abs(ageNorm - 0.5)); // simple size calculation
		//ellipse(this.loc.x, this.loc.y, size, size); // draw particles as discs
		rect(this.loc.x, this.loc.y, size, size); // draw particles as squares (maybe a little faster)
		pop();
	}
}

